626	function readmeGp(itemPart: string, params: Param[], name: string, command: string, ns: string, version: string, menus: MenuDesign[], quests: QuestDesign[], notes: string[], boss?: { sections: string[]; commands: string[]; huds?: boolean }): string {
627	  const lines = [`# ${name}`, ``, boss ? `Made with the Cyrus designers (items, menus, quests, bosses${boss.huds ? ", encounters and HUDs" : " and encounters"}) for Minecraft ${version}.` : `Items, menus and quests made with the Cyrus designers for Minecraft ${version}.`, ``];
628	  if (itemPart.trim()) lines.push(itemPart.trim(), ``);
629	  if (menus.length) lines.push(`## Menus`, ``);
630	  for (const m of menus) {
631	    const ow = m.openWith ?? {};
632	    const how = [ow.command !== false ? `\`/${command} menu ${m.id}\`` : "", ow.item ? `right-click with ${ow.item.replace(/_/g, " ")}` : "", ow.npc ? `right-click an entity tagged \`${ns}.npc.${m.id}\`` : ""].filter(Boolean).join(", ") || "from another menu";
633	    lines.push(`- **${m.title}** (${m.style}${m.style === "chest" ? `, ${m.rows} rows` : ""}): open with ${how}.${m.permission ? ` Needs ${ns}.${m.permission}.` : ""}`);
634	    for (const { c } of menuClickables(m)) if (c.cost) lines.push(`  - ${c.icon.name?.text ?? (c.icon.material ? bare(c.icon.material).replace(/_/g, " ") : c.icon.item)}${costText(c.cost)}${c.permission ? ` (${ns}.${c.permission})` : ""}`);
635	    if (m.style === "chest" && m.list?.source.type === "config") lines.push(`  - Shop lines from config.yml \`lists.${m.id}\` (${m.list.source.entries.length} by default, ${m.list.slots.length} per page).`);
636	  }
637	  if (menus.length) lines.push(``);
638	  if (quests.length) lines.push(`## Quests`, ``);
639	  for (const q of quests) {
640	    const mode = q.repeat?.mode ?? "once";
641	    lines.push(`- **${q.title}**${q.description ? `: ${q.description}` : ":"} ${(q.start ?? "command") === "menu" ? "Started from a menu." : `Start with \`/${command} quests start ${q.id}\`.`}${q.requires?.length ? ` Needs ${q.requires.join(", ")} first.` : ""}${mode !== "once" ? ` Repeats${mode === "repeatable" ? "" : ` ${mode}`} (cooldown ${secs(repeatCooldown(q))}).` : ""}`);
642	    q.steps.forEach((s, i) => lines.push(`  ${i + 1}. ${s.text} (${s.objectives.map(OBJ_WORDS).join(", ")})`));
643	    for (const b of q.branches?.options ?? []) lines.push(`  - Path "${b.label.text}": ${b.steps.map((s) => `${s.text} (${s.objectives.map(OBJ_WORDS).join(", ")})`).join("; ")}`);
644	  }
645	  if (quests.length) lines.push(``);
646	  if (boss) lines.push(...boss.sections);
647	  lines.push(...settingsLines(params, name, command));
648	  lines.push(``, `## Commands and permissions`, ``);
649	  if (!boss || menus.length || quests.length) lines.push(
650	    `- \`/${command} menu <id> [player]\` (${ns}.menu: everyone; other players ${ns}.menu.others), \`/${command} menu list\`, \`/${command} menu costs <id>\` (${ns}.command)`,
651	    `- \`/${command} quests\`, \`quests log\`, \`quests start|abandon|info|choose <id>\` (${ns}.quests: everyone); \`quests list\`, \`quests check\` (${ns}.command); \`quests reset <player>\` (${ns}.quests.admin)`);
652	  if (boss) lines.push(...boss.commands);
653	  lines.push(`- \`/${command} give <item> [player] [count]\` (${ns}.give), \`/${command} list\`, \`/${command} params [id]\` (${ns}.command), \`/${command} reload\` (${ns}.reload); operators by default`);
654	  for (const p of [...menus.flatMap((m) => m.permissions ?? []), ...quests.flatMap((q) => q.permissions ?? [])]) lines.push(`- ${ns}.${p.node}: ${p.description} (default ${p.default})`);
655	  if (notes.length) lines.push(``, `## Good to know`, ``, ...notes.map((n) => `- ${n}`));
656	  lines.push(``);
657	  return lines.join("\n");
658	}
