689	  const money = menus.some((m) => menuClickables(m).some(({ c }) => c.cost?.type === "economy") || (m.style === "chest" && m.list?.source.type === "config" && m.list.source.currency.type === "economy"));
690	  const files: CompiledFile[] = [];
