751	  if (ms) add(`${dir}/designer/ModelStates.java`, renderComponent(MODEL_STATES_JAVA, pkg), "component");
752	  add(`${dir}/${mainCls}.java`, ext
753	    ? mainClassAll(pkg, mainCls, ctx.namespace, command, { items: itemClasses, menus: menuClasses, quests: questClasses, bosses: bossClasses, encounters: encounterClasses, huds: hudClasses }, { ...ids, bosses: bosses.map((b) => b.id), encounters: encounters.map((e) => e.id), huds: huds.map((h) => h.id) }, !!ctx.customHooks, money, ms)
