1	// Cyrus R3 gameplay designers, part 3: metadata of the BOSS / ENCOUNTER components (purpose, families, limits, how they
2	// are tested) + the per-version BossCompat + the library hash. "Verified" means exactly what it means for the item and
3	// gameplay libraries: javac against the real Paper classpaths of 1.21.11 (JDK 21) and 26.2 (JDK 25) with zero warnings,
4	// the strict safety scan on bytecode + source, and a Test Flight boot with RCON checks (test/cyrus-boss-real.ts). Other
5	// registry versions use the same sources and their BossCompat variant, compiled per the API sheets, NOT by javac.
6	import { createHash } from "node:crypto";
7	import { COMPONENTS as ITEM_COMPONENTS, COMPONENT_LIBRARY_VERSION, compatSource, type ComponentMeta } from "../components";
8	import type { DesignFeatures } from "../spec";
9	import { BOSS_LIMITS } from "./spec";
10	import * as J from "./java";
11	
12	export const BOSS_LIBRARY_VERSION = "cyrus-boss-components-1";
13	
14	const ALL: ("1.21" | "26")[] = ["1.21", "26"];
15	const UNIT = "test/cyrus-boss.test.ts (pure: present in every boss compile, strict-scan text rules, precheck, golden hashes, TS simulator twin)";
16	const REAL = "test/cyrus-boss-real.ts (javac 1.21.11/JDK 21 + 26.2/JDK 25 with 0 warnings, strict scan, Test Flight boot + RCON)";
17	
18	export const BOSS_COMPONENTS: ComponentMeta[] = [
19	  { id: "boss-def", file: "designer/BossDef.java", purpose: "base of every generated boss: phases, attacks, stats, scaling math, drops table, bar style", families: ALL, limits: [`${BOSS_LIMITS.maxPhases} phases (thresholds forced to go down)`, `${BOSS_LIMITS.maxAttacks} attacks`, "health 1-1024 after scaling"], tests: [UNIT, REAL, "Test Flight: boss list / check (scaling math on the JVM == TS)"], source: J.BOSSDEF_JAVA },
20	  { id: "boss-cast", file: "designer/BossCast.java", purpose: "one attack: the boss, its targets (re-checked: alive + in the arena), the damage multiplier, the shared Budget", families: ALL, limits: ["the item library's Budget: 64 actions, 32 entities, 512 particles, 3 projectiles, 8 tasks per attack"], tests: [UNIT, REAL], source: J.BOSSCAST_JAVA },
21	  { id: "boss-effects", file: "designer/BossEffects.java", purpose: "every boss action: damage (boss as source), knockback, pull, potion, projectile, particles, sound, texts, leap, summon, heal, self effect", families: ALL, limits: ["velocity <= 4 blocks/tick", "projectiles removed after 5 s, arrows not pickable, fireballs set no fire and break nothing", `summons <= ${BOSS_LIMITS.summonsPerAttack} per attack, minions.maxAlive per boss, ${BOSS_LIMITS.liveMinions} plugin-wide`], tests: [UNIT, REAL, "Test Flight: boss cast damages / summons (test targets)"], source: J.BOSSEFFECTS_JAVA },
22	  { id: "boss-drops", file: "designer/DropTable.java", purpose: "drops: vanilla items, design items (with identity), one loot table of the project's data pack; seeded Random", families: ALL, limits: [`${BOSS_LIMITS.maxDrops} item entries`, "loot table results capped at 27 stacks", "boss equipment and minion / wave-mob drops never drop"], tests: [UNIT, REAL, "Test Flight: boss check drop sample == TS; ground drops on kill"], source: J.DROPTABLE_JAVA },
23	  { id: "boss-instance", file: "designer/BossInstance.java", purpose: "state of one live boss (phase, cooldowns, damage shares, minions, bar viewers)", families: ALL, limits: ["dropped on death, despawn, disable"], tests: [UNIT, REAL], source: J.BOSSINSTANCE_JAVA },
24	  { id: "boss-runtime", file: "designer/Bosses.java", purpose: "the bosses hub: one shared AI timer (10 ticks), arena (leash, participants, empty despawn, time out / enrage), phases, weighted attacks, boss bar, drops, minions, cleanup + leftover sweep, summon items, immunities", families: ALL, limits: [`${BOSS_LIMITS.liveBosses} live bosses`, "one timer per mod (not per boss)", "never persistent: an unloaded fight ends; leftovers removed on chunk load and enable", "our mobs never hurt / target / burn / convert / break blocks"], tests: [UNIT, REAL, "Test Flight: spawn, status, phase by damage, leash, despawn when empty, kill -> drops + minions removed, clamping, migration"], source: J.BOSSES_JAVA },
25	  { id: "encounter-def", file: "designer/EncounterDef.java", purpose: "base of every generated encounter: waves (mob class literals or boss ids), rewards, arena", families: ALL, limits: [`${BOSS_LIMITS.maxWaves} waves`, `${BOSS_LIMITS.maxWaveSpawns} spawn entries per wave`], tests: [UNIT, REAL], source: J.ENCOUNTERDEF_JAVA },
26	  { id: "encounter-runtime", file: "designer/Encounters.java", purpose: "waves: delay, cleared / timer advance, time limits, empty-arena failure, rewards by damage share, bar", families: ALL, limits: [`${BOSS_LIMITS.liveEncounters} running encounters`, `${BOSS_LIMITS.encounterMobs} mobs each`, "wave mobs drop nothing"], tests: [UNIT, REAL, "Test Flight: start, wave advance after a kill, complete with ground rewards"], source: J.ENCOUNTERS_JAVA },
27	  { id: "boss-command", file: "designer/BossCommand.java", purpose: "boss / encounter subcommands wrapping the mod command (list, status, check, spawn, despawn, cast; encounter start / stop); reload + params include bosses", families: ALL, limits: ["admin subcommands <ns>.boss.admin (operators)", "summon items <ns>.boss.summon (everyone)"], tests: [UNIT, REAL, "Test Flight: RCON boss + encounter subcommands"], source: J.BOSSCOMMAND_JAVA },
28	];
29	
30	/** The per-version Java of the boss library: attribute constants (GENERIC_ prefix before 1.21.3). */
31	export function bossCompatSource(fe: DesignFeatures): string {
32	  const p = fe.attributeNames === "generic-prefix" ? "GENERIC_" : "";
33	  return `package __PKG__.designer;
34	
35	import org.bukkit.attribute.Attribute;
36	
37	/** Component boss-compat v1: the per-version attribute constants of the boss library (Minecraft ${fe.version}, attributes ${fe.attributeNames}). */
38	public final class BossCompat {
39	    public static final Attribute MAX_HEALTH = Attribute.${p}MAX_HEALTH;
40	    public static final Attribute ARMOR = Attribute.${p}ARMOR;
41	    public static final Attribute ATTACK_DAMAGE = Attribute.${p}ATTACK_DAMAGE;
42	    public static final Attribute MOVEMENT_SPEED = Attribute.${p}MOVEMENT_SPEED;
43	    public static final Attribute KNOCKBACK_RESISTANCE = Attribute.${p}KNOCKBACK_RESISTANCE;
44	    public static final Attribute FOLLOW_RANGE = Attribute.${p}FOLLOW_RANGE;
45	
46	    private BossCompat() {}
47	}
48	`;
49	}
50	export const BOSS_COMPAT_META: Omit<ComponentMeta, "source"> = { id: "boss-compat", file: "designer/BossCompat.java", purpose: "per-version attribute constants (GENERIC_ names on 1.21.1)", families: ALL, limits: [], tests: [UNIT, REAL] };
51	
52	/** Hash of the library a boss mod is built from (item components + boss components + the compat template). */
53	export function bossLibraryHash(): string {
54	  const h = createHash("sha256");
55	  h.update(COMPONENT_LIBRARY_VERSION);
56	  h.update(BOSS_LIBRARY_VERSION);
57	  for (const c of [...ITEM_COMPONENTS, ...BOSS_COMPONENTS]) { h.update(c.id); h.update(c.source); }
58	  h.update(compatSource({ version: "x", itemModel: true, attributeNames: "plain", javaRelease: 21, scheduling: "paper" }));
59	  h.update(bossCompatSource({ version: "x", itemModel: true, attributeNames: "plain", javaRelease: 21, scheduling: "paper" }));
60	  return h.digest("hex");
61	}
