561	  // gameplay (Cyrus R3 menus + quests): part of the designer route; only with design
562	  const gameplay = design && raw.gameplay === true;
563	  // bosses (Cyrus R3 bosses + encounters): part of the designer route; only with design
564	  const bosses = design && raw.bosses === true;
565	  // hud (Cyrus R4 glyph HUDs): part of the designer route; only with design
566	  const hud = design && raw.hud === true;
567	  // motion props (Cyrus motion core): part of the designer route; only with design
568	  const motion = design && raw.motion === true;
569	  const out = { texture, sound: raw.sound === true, library: raw.sound === true && raw.library === true, namespace: raw.namespace, notes, ...(datapack ? { datapack: true } : {}), ...(design ? { design: true } : {}), ...(gameplay ? { gameplay: true } : {}), ...(bosses ? { bosses: true } : {}), ...(hud ? { hud: true } : {}), ...(motion ? { motion: true } : {}), ...(worldgen ? { worldgen: true } : {}) };
570	  // Cyrus R3: creatures only on versions with animatedCreatures that this service builds, and only when the BetterModel
571	  // API jars are installed and verified (defence in depth; the portal decided the plan gate). Absent = byte-identical.
572	  if (raw.creature !== undefined) {
573	    let creature = raw.creature === true;
574	    if (creature && !creatureVersions.has(mcVersion)) { creature = false; notes.push(`creatures are off: Minecraft ${mcVersion} has no animated creature support on this builder`); }
575	    if (creature && !creatureReady(mcVersion)) { creature = false; notes.push("creatures are off: the BetterModel API is not installed on this builder"); }
576	    // rc13 (boss-minions): the designer route compiles the whole plugin from designs and writes no plugin code the model
577	    // could attach a BetterModel model with, so a creature lane next to designs was planned, paid for and never delivered.
578	    // Switched off up front (no creature prompt section, no repair rounds) and reported as a lane gap.
579	    if (creature && design) { creature = false; notes.push("creatures are off: this build is made with the item designer, which compiles the whole plugin and cannot attach a custom creature model; the mob keeps a vanilla body"); out.laneOff = { ...(out.laneOff || {}), creature: "the item designer compiles the whole plugin from designs and cannot attach a custom creature model, so the boss keeps a vanilla mob body" }; }
580	    out.creature = creature;
581	  }
582	  if (Array.isArray(raw.plan) && raw.plan.length) out.plan = raw.plan.map((x) => ({ lane: x.lane, what: String(x.what).replace(/[<>\r\n]/g, " ").slice(0, 200) }));
583	  // Cyrus Config Studio: declared settings (never with the designer, which owns config.yml). Absent = byte-identical.
584	  if (raw.config === true && !design) { out.config = true; out.configTemplates = raw.configTemplates || []; }
585	  else if (raw.config === true) notes.push("the settings schema is not used: the item designer writes this mod's config.yml");
586	  // Cyrus R3 item model states: ride on the texture route (same plan gate); off when textures are off. Absent = byte-identical.
587	  if (legacy) out.legacy = true;
588	  if (raw.itemmodel !== undefined) {
589	    out.itemmodel = raw.itemmodel === true && texture && !legacy;
590	    if (raw.itemmodel === true && !texture) notes.push("item model states are off: custom textures are off for this build");
591	  }
592	  // Cyrus armor + custom-block lanes (portal switches CYRUS_ARMOR_LANE / CYRUS_NOTEBLOCK_LANE): only on the texture route.
593	  // Absent = byte-identical.
594	  for (const k of ["armor", "blocks"]) if (raw[k] !== undefined) {
595	    out[k] = raw[k] === true && texture;
596	    if (raw[k] === true && !texture) notes.push(`custom ${k === "armor" ? "armor sets" : "blocks"} are off: custom textures are off for this build`);
597	  }
598	  return out;
599	}
