52:export type CompileContext = {
764:export function compileDesigns(inputs: unknown[], ctx: CompileContext): CompileResult {
870:export function modelStatesOf(designs: ItemDesign[], fe: DesignFeatures, ctx: Pick<CompileContext, "assets">): MainStates | null {
  version: string;
  namespace: string;
  pluginName: string;
  pluginVersion?: string;
  description?: string;
  /** Free-form extension code exists at src/main/java/<pkg>/custom/CustomHooks.java (enable(JavaPlugin) / disable()). */
  customHooks?: boolean;
  /** The previous build's config.yml text: config_version is kept when the designer values did not change, else bumped. */
  previousConfig?: string;
  /** Exact config_version to emit (the portal re-compile reproduces the service's); wins over previousConfig. */
  configVersion?: number;
  assets?: DesignContext["assets"];
  /** Technique kinds allowed (break_block, vein_break); absent = the CYRUS_MC_TECHNIQUES / MB_MC_TECHNIQUES switch. */
  techniques?: boolean;
};

export type CompiledFile = { path: string; content: string; sha256: string; role: "component" | "compat" | "generated" | "resource" };
export type CompileOk = {
  ok: true; files: CompiledFile[]; readme: string; readmeSha256: string; hash: string; params: Param[]; warnings: DzIssue[]; notes: string[];
  pkg: string; mainClass: string; command: string; modelsApplied: string[]; configVersion: number; designerValuesHash: string; features: DesignFeatures;
  javacVerified: boolean; compiler: string; library: string; libraryHash: string; designs: ItemDesign[];

// Cyrus R3 gameplay designers, part 2: the MOD COMPILER for menus and quests. `compileMod(inputs, ctx)` takes every
// design file of a mod (items, menus, quests). A mod with only item designs is compiled by the unchanged item compiler
// (../compile.ts compileDesigns: byte-identical output, same golden hashes). A mod with menus or quests gets the item
// library + the gameplay library (./components) + generated straight-line classes (items/, abilities/, menus/, quests/),
// a main class that wires both hubs, plugin.yml and config.yml. Every number and text of a menu or quest (prices,
// counts, cooldowns, titles, texts, coordinates) is a config.yml PARAMETER under menus.<id>. / quests.<id>., so a value
// edit changes config.yml (+ README) only, never a Java file (./params.ts proves it). Deterministic: same designs +
// context = same bytes (golden hashes in test/fixtures/cyrus-gameplay/golden.json).
import { vanillaIds } from "../../datapack/versions";
import { withHard, type CapRange } from "../../limits/range";
import { COMPAT_META, COMPONENTS, compatSource, renderComponent } from "../components";
import { MODEL_STATES_JAVA } from "../components/states";
import {
