    ...(money ? [`        if (getServer().getPluginManager().getPlugin("Vault") != null) gameplay.money(new VaultMoney());`] : []),
    ...(hb ? [`        bosses.enable(getCommand(${jstr(command)}), List.of(${cls.bosses.map((c) => `new ${c}(bosses)`).join(", ")}), List.of(${cls.encounters.map((c) => `new ${c}(bosses)`).join(", ")}), ${others}, ${gp});`] : []),
