    private final Budget budget;

    private BossCast(Bosses b, BossInstance inst, List<LivingEntity> targets, LivingEntity target, double mult, Budget budget) {
        this.b = b; this.inst = inst; this.targets = targets; this.target = target; this.mult = mult; this.budget = budget;
    }

    static BossCast of(Bosses b, BossInstance inst, List<LivingEntity> targets, double mult) { return new BossCast(b, inst, new ArrayList<>(targets), null, mult, new Budget()); }

    /** The same cast (same budget) aimed at one target: the per-target actions. */
    public BossCast at(LivingEntity t) { return new BossCast(b, inst, targets, t, mult, budget); }

    /** Targets still alive and inside the arena (re-checked for delayed steps). */
    public List<LivingEntity> targets() {
        List<LivingEntity> out = new ArrayList<>();
        for (LivingEntity t : targets) if (t.isValid() && !t.isDead() && b.inArena(inst, t.getLocation())) out.add(t);
        return out;
    }

    public LivingEntity first() { List<LivingEntity> t = targets(); return t.isEmpty() ? null : t.get(0); }
    public LivingEntity target() { return target; }
    public Mob boss() { return inst.mob; }
    public BossInstance instance() { return inst; }
    public Bosses bosses() { return b; }
    public double mult() { return mult; }
    public Budget budget() { return budget; }
    public boolean valid() { return inst.mob.isValid() && !inst.mob.isDead() && b.alive(inst); }

    /** Run a step later (one task from the budget; skipped when the boss is gone). */
    public void later(long delay, Runnable step) {
        if (!budget.task()) return;
        b.designer().tasks().later(delay, () -> { if (valid()) step.run(); });
    }
}
`;

export const ENCOUNTERDEF_JAVA = String.raw`package __PKG__.designer;

import java.util.ArrayList;
