/**
 * Component encounter-def v1: the base of every generated encounter. Structure (waves, their spawns: mob class literals
 * or boss ids, advance rules) in the generated constructor / spawnWave(); numbers and texts in load() (config.yml
 * encounters.<id>.*).
 */
public abstract class EncounterDef {
    public static final class Wave {
        public final boolean cleared;
        public long delayTicks;
        public long ticks;
        public String message = "";
        public int size;
        Wave(boolean cleared) { this.cleared = cleared; }
    }

    /** What a wave's generated code spawns through (the hub caps and tags every mob). */
    public interface Spawner {
        <T extends Mob> void mob(Class<T> type, Material weapon, int count);
        void boss(String id);
    }

    protected final Bosses b;
    private final String id;
    public final List<Wave> waves = new ArrayList<>();
    public final DropTable rewards = new DropTable();
    public BossBar.Color barColor = BossBar.Color.PURPLE;
    public BossBar.Overlay barOverlay = BossBar.Overlay.PROGRESS;
    public boolean command = true;
    public String startItem;
    public String title = "";
    public double radius = 24;
    public long cooldownTicks;
    public int maxAlive = 12;
    public long emptyTicks = 1200;
    public long timeLimitTicks;
    public String msgStart = "";
    public String msgComplete = "";
    public String msgFail = "";

    protected EncounterDef(Bosses b, String id) { this.b = b; this.id = id; }

    public final String id() { return id; }
    protected final Wave wave(boolean cleared) { Wave w = new Wave(cleared); waves.add(w); return w; }
    public abstract void load(DesignConfig c);
    public abstract void spawnWave(int index, Spawner s);
    public void describe(List<String> out) {}

    public final String describeDef() {
        StringBuilder s = new StringBuilder(id).append(": waves=").append(waves.size()).append(" sizes=");
        for (int i = 0; i < waves.size(); i++) s.append(i == 0 ? "" : ",").append(waves.get(i).size).append(waves.get(i).cleared ? "c" : "t");
        s.append(" max_alive=").append(maxAlive).append(" arena=").append(BossDef.fmt(radius)).append(" start=").append(command ? "command" : "-").append(startItem == null ? "" : ",item:" + startItem);
        s.append(" rewards=").append(rewards.mode().name().toLowerCase(java.util.Locale.ROOT)).append('/').append(rewards.size());
        return s.toString();
    }
}
`;

