/**
 * Cyrus boss model: the ONLY boss component that uses the BetterModel API (kr.toxicity.model.api, compile-only; the server
 * runs the Nxeon-managed BetterModel: 2.2.0 on 1.21.x, 3.5.0 on 26.x). Emitted only when a boss, minion or wave mob wears
 * a creature rig of the mod; the mod then declares depend: [BetterModel]. Uses only members present in BOTH API lines
 * (javap-checked 2026-10-15): BetterModel.modelOrNull, ModelRenderer.getOrCreate(BukkitAdapter.adapt(entity)),
 * Tracker.height / scaler(ModelScaler.value) / animate / isClosed / close, EntityTracker.damageTint. BetterModel plays the
 * rig's looping idle / walk clips itself (built-in tracker animations follow the mob's movement); this class plays the
 * one-shot clips the boss runtime asks for, scales the base mob's hitbox (scale attribute) to the model's height, and
 * closes every model it opened (despawn, death, unloaded chunk via sweep, disable).
 */
export const BOSSMODELS_JAVA = String.raw`package __PKG__.designer;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.UUID;
import kr.toxicity.model.api.BetterModel;
import kr.toxicity.model.api.animation.AnimationModifier;
import kr.toxicity.model.api.bukkit.platform.BukkitAdapter;
import kr.toxicity.model.api.data.renderer.ModelRenderer;
import kr.toxicity.model.api.tracker.EntityTracker;
import kr.toxicity.model.api.tracker.ModelScaler;
import org.bukkit.attribute.AttributeInstance;
import org.bukkit.entity.Mob;

/** Component boss-model v1: creature models (BetterModel trackers) worn by bosses, minions and wave mobs. */
public final class BossModels implements Bosses.Body {
    /** Open models at once (4 bosses + 48 minions + 2 x 24 wave mobs fit). */
    public static final int MAX_MODELS = 104;
    public static final double MIN_SCALE = 0.25;
    public static final double MAX_SCALE = 4.0;
    /** Ticks a death clip may play before the model is closed (the game removes a dead mob after 20 ticks anyway). */
    public static final long DEATH_TICKS = 60;

    private static final class Worn {
        final Mob mob;
        final String key;
        final double height;
        final double hitbox;
        EntityTracker tracker;
        long closeAt = -1;
        Worn(Mob mob, String key, EntityTracker tracker, double height, double hitbox) { this.mob = mob; this.key = key; this.tracker = tracker; this.height = height; this.hitbox = hitbox; }
    }

    private final Bosses b;
    private final Map<UUID, Worn> worn = new HashMap<>();

    public BossModels(Bosses b) { this.b = b; }

    @Override
    public String attach(Mob m, String key, double scale) {
        if (worn.size() >= MAX_MODELS) return "already " + MAX_MODELS + " creature models alive";
        try {
            ModelRenderer r = BetterModel.modelOrNull(key);
            if (r == null) return "BetterModel has no model " + key + " loaded";
            EntityTracker t = r.getOrCreate(BukkitAdapter.adapt(m));
            if (t == null) return "BetterModel did not attach " + key;
            float s = (float) Math.max(MIN_SCALE, Math.min(MAX_SCALE, scale));
            double h = t.height();
            t.scaler(ModelScaler.value(s));
            double base = m.getHeight();
            double hit = 1.0;
            if (h > 0 && base > 0) {
                hit = Math.max(MIN_SCALE, Math.min(MAX_SCALE, h * s / base));
                AttributeInstance a = m.getAttribute(BossCompat.SCALE);
                if (a != null) a.setBaseValue(hit);
            }
            t.animate("idle");
            worn.put(m.getUniqueId(), new Worn(m, key, t, h * s, hit));
            return null;
        } catch (RuntimeException e) {
            return "BetterModel failed: " + e.getClass().getSimpleName();
        }
    }

    /** The open tracker of a mob (re-attached once when BetterModel closed it, e.g. after /bettermodel reload). */
    private EntityTracker live(Mob m) {
        Worn w = worn.get(m.getUniqueId());
        if (w == null || w.closeAt >= 0) return null;
        if (w.tracker.isClosed() && m.isValid() && !m.isDead()) {
            try {
                ModelRenderer r = BetterModel.modelOrNull(w.key);
                w.tracker = r == null ? w.tracker : r.getOrCreate(BukkitAdapter.adapt(m));
            } catch (RuntimeException e) { return null; }
        }
        return w.tracker.isClosed() ? null : w.tracker;
    }

    @Override
    public void play(Mob m, String clip) {
        EntityTracker t = live(m);
        if (t != null && clip != null) t.animate(clip, AnimationModifier.DEFAULT_WITH_PLAY_ONCE);
    }

    @Override
    public void hurt(Mob m, String clip) {
        EntityTracker t = live(m);
        if (t == null) return;
        if (clip != null) t.animate(clip, AnimationModifier.DEFAULT_WITH_PLAY_ONCE);
        t.damageTint();
    }

    @Override
    public void death(Mob m, String clip) {
        EntityTracker t = live(m);
        Worn w = worn.get(m.getUniqueId());
        if (w == null) return;
        if (t != null && clip != null) t.animate(clip, AnimationModifier.DEFAULT_WITH_PLAY_ONCE);
        w.closeAt = b.designer().now() + DEATH_TICKS;
    }

    @Override
    public void detach(Mob m) {
        Worn w = worn.remove(m.getUniqueId());
        if (w != null && !w.tracker.isClosed()) w.tracker.close();
    }

    @Override
    public boolean wears(Mob m) {
        Worn w = worn.get(m.getUniqueId());
        return w != null && w.closeAt < 0 && !w.tracker.isClosed();
    }

    @Override
    public String describe(Mob m) {
        Worn w = worn.get(m.getUniqueId());
        if (w == null) return "vanilla body";
        return "model " + w.key + (wears(m) ? " attached" : " closed") + String.format(Locale.ROOT, ", height %.2f, hitbox x%.2f", w.height, w.hitbox);
    }

    @Override
    public int sweep(long now) {
        int n = 0;
        for (UUID u : new ArrayList<>(worn.keySet())) {
            Worn w = worn.get(u);
            boolean gone = !w.mob.isValid() && !w.mob.isDead();
            boolean dyingDone = w.closeAt >= 0 && (now >= w.closeAt || !w.mob.isValid() && w.mob.isDead() && now >= w.closeAt);
            if (gone || dyingDone || (w.closeAt < 0 && w.mob.isDead())) {
                if (w.closeAt < 0 && w.mob.isDead()) { w.closeAt = now + DEATH_TICKS; continue; }
                worn.remove(u);
                if (!w.tracker.isClosed()) w.tracker.close();
                n++;
            }
        }
        return n;
    }

    @Override
    public int closeAll() {
        int n = 0;
        for (Worn w : worn.values()) if (!w.tracker.isClosed()) { w.tracker.close(); n++; }
        worn.clear();
        return n;
    }
}
`;
