  const snd = assets.sound ? ` Custom sounds are allowed: put them in assets/sounds/<set>.json and play each event as "${assets.namespace}:<set>.<event>".${assets.library ? " The sound library catalog is at sound-library/catalog.txt." : ""}` : "";
