  const dz = assets.design ? ` DESIGN BUILD: write the design file(s) FIRST, before any Java; this build fails without at least one assets/designs/<id>.json, and Nxeon generates plugin.yml, config.yml and the main class from them (do not write those). Use a design for every part that fits: an item with abilities, a menu / shop / warp or kit list (GUI), a quest, a boss or wave encounter, a HUD (action bar, boss bar, sidebar). Only what no design can express goes into the custom/ classes. If NOTHING in this request fits a design, write an ordinary plugin instead (plugin.yml, main class, no design file). Item designs are used: put them in assets/designs/<id>.json; an item's full id is "${assets.namespace}:<id>" and a custom texture's item model is "${assets.namespace}:<texture name>".${assets.gameplay ? ` Menus and quests are designs in the same folder ("kind":"menu" / "quest"); NPC menus open on entities tagged ${assets.namespace}.npc.<menu id>.` : ""}${assets.bosses ? ` Bosses and encounters are designs in the same folder ("kind":"boss" / "encounter"); boss mobs carry the scoreboard tag ${assets.namespace}.boss.` : ""}${assets.hud ? ` HUDs are designs in the same folder ("kind":"hud"); their glyphs live in the font ${assets.namespace}:hud of this mod's pack.` : ""}` : "";
  const opt = (assets.texture || assets.sound) && !(Array.isArray(assets.plan) && assets.plan.length) ? " Custom assets are optional: create them only where they make this mod better, and never describe an asset in modbuilder.json that you did not create." : "";
  const cf = (assets.texture || assets.sound) && !assets.creature ? CREATURE_FALLBACK : "";
  return `\nThis mod's reserved namespace is ${assets.namespace}.${tex}${ims}${snd}${dp}${dz}${cre_}${opt}${cf}\n${configBlock(assets)}${planBlock(assets)}`;
