/** Boss "The Hollow King" (nx_b0ssm0de:hollow_king, wither_skeleton). Generated by Cyrus from assets/designs/hollow_king.json (do not edit). Parameters: config.yml bosses.hollow_king. */
public final class HollowKingBoss extends BossDef {

    public HollowKingBoss(Bosses b) {
        super(b, "hollow_king", "wither_skeleton");
        command = true;
        barColor = BossBar.Color.PURPLE;
        barOverlay = BossBar.Overlay.NOTCHED_10;
        showPhase = true;
        nameColor = NamedTextColor.LIGHT_PURPLE;
        modelKey = "nx_b0ssm0de_hollow_king";
        modelScale = 1.00;
        clipPhase = "hurt";
        modelSounds.put("ambient", "nx_b0ssm0de:hollow_king.ambient");
        modelSounds.put("attack", "nx_b0ssm0de:hollow_king.attack");
        modelSounds.put("death", "nx_b0ssm0de:hollow_king.death");
        modelSounds.put("hurt", "nx_b0ssm0de:hollow_king.hurt");
        Attack a0 = attack("royal_strike", Select.NEAREST);
        a0.telegraphParticle = Particle.SOUL;
        Attack a1 = attack("call_thralls", Select.SELF);
        Phase p0 = phase("court");
        p0.attacks.add("royal_strike");
        p0.attacks.add("call_thralls");
        Phase p1 = phase("ruin");
        p1.attacks.add("royal_strike");
        p1.attacks.add("call_thralls");
        p1.effects.add(PotionEffectType.SPEED);
    }

    @Override
    public Mob spawnBase(Location at, Consumer<Mob> init) {
        Consumer<WitherSkeleton> c = init::accept;
        return at.getWorld().spawn(at, WitherSkeleton.class, false, c);
    }

    @Override
    public void equip(Mob m) {
        EntityEquipment eq = m.getEquipment();
        if (eq == null) return;
        eq.setItemInMainHand(display(Material.STONE_SWORD));
    }

    @Override
    public void load(DesignConfig c) {
        phases.get(0).weights.clear();
        phases.get(1).weights.clear();
        phases.get(1).amplifiers.clear();
        drops.clear();
        drops.mode(DropTable.Mode.PARTICIPANTS);
    }

    @Override
    public void attack(int index, BossCast c) {
        BossEffects fx = c.bosses().effects();
        switch (index) {
            case 0 -> attack0(c, fx);
            case 1 -> attack1(c, fx);
            default -> { }
        }
    }

    @Override
    public void enter(int index, BossCast c) {
        BossEffects fx = c.bosses().effects();
        switch (index) {
            case 1 -> enter1(c, fx);
            default -> { }
        }
    }

    /** Attack royal_strike (nearest, at most 2). */
        // a0: damage
        // a1: knockback
    }

    /** Attack call_thralls (self). */
        // a0: summon
        if (!c.budget().action()) return;
        // a1: spawn_particles
        if (!c.budget().action()) return;
    }

    /** Phase ruin starts (targets: every participant, nearest first, at most 8). */
        // a0: title
        if (!c.budget().action()) return;
    }

    @Override
    public void describe(List<String> out) {
    }
