// Cyrus boss model (pure): a designer BOSS (and its minions / wave mobs) WEARS a creature rig of the mod. The additive
// schema field (boss "model", summon / wave "rig"), the cross-reference checks (rig exists, sounds, clips) with the
// explicit vanilla fallback, the compiler output (BossModels only when a rig is worn, depend: [BetterModel], the
// version's BetterModel API deps, golden hashes), TS == the generated service JS, the service lane rule (creature kept next
// to the bosses part only with MB_BOSS_MODEL=1), the prompt addition (tiny, absent otherwise), the creature soft checks on
// the designer route, the lane-gap rule (a worn creature is delivered), the portal re-compile and the oracle probes.
// Real javac + a real Test Flight: test/cyrus-boss-model-real.ts (node-2).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { validateGameplay } from "../lib/cyrus/designer/gameplay/spec";
import { compileMod } from "../lib/cyrus/designer/gameplay/compile";
import { checkReturnedDesigns } from "../lib/cyrus/designer/sync";
import { rigsWorn, type BossDesign } from "../lib/cyrus/designer/boss/spec";
import { BOSS_MODEL_COMPONENT, bossModelDeps } from "../lib/cyrus/designer/boss/components";
import { deriveExpectations } from "../lib/cyrus/testflight/oracle/derive";
import { BM_NS as NS, BM_PLUGIN, BM_RIGS, BM_VERSIONS, bmModels, compileBm, loadBmDesigns, loadBmRig } from "../scripts/cyrus/boss-model-golden";
import { BOSS_NS, BOSS_PLUGIN, loadBossFixtures } from "../scripts/cyrus/boss-golden";

const ROOT = path.join(__dirname, "..");
const FX = path.join(__dirname, "fixtures/cyrus-boss-model");
const king = (): BossDesign => structuredClone(loadBmDesigns()[0]);
const siege = () => structuredClone(loadBmDesigns()[1]);
const fileOf = (r: { files: { path: string; content: string }[] }, end: string) => r.files.find((f) => f.path.endsWith(end))?.content ?? "";
const v = (inputs: unknown[], rigs?: string[]) => validateGameplay(inputs, { version: "1.21.11", namespace: NS, ...(rigs ? { assets: { rigs } } : {}) });
const codes = (inputs: unknown[], id: string, rigs?: string[], what: "errors" | "warnings" = "warnings") => (v(inputs, rigs).files.find((f) => f.id === id)?.[what] ?? []).map((e) => e.code);

describe("boss model: schema + cross-references", () => {
  it("the golden mod is valid; the rigs it wears", () => {
    const r = v(loadBmDesigns(), BM_RIGS);
    assert.ok(r.ok, JSON.stringify(r.errors));
    assert.deepEqual(rigsWorn(r.bosses, r.encounters), ["hollow_king", "hollow_thrall"]);
    assert.deepEqual(codes(loadBmDesigns(), "hollow_king", BM_RIGS).filter((c) => c.startsWith("rig_")), []);
  });
  it("is additive: unknown model keys refused, scale capped, a boss wave spawn cannot carry a rig", () => {
    const k = king(); (k.model as Record<string, unknown>).color = "red";
    assert.ok(codes([k, siege()], "hollow_king", BM_RIGS, "errors").includes("schema"));
    const s = king(); s.model!.scale = 9;
    assert.ok(codes([s, siege()], "hollow_king", BM_RIGS, "errors").includes("schema"));
    const ok = king(); ok.model!.scale = 1.5;
    assert.deepEqual(codes([ok, siege()], "hollow_king", BM_RIGS, "errors"), []);
    const e = siege(); e.waves[1].spawns[0].rig = "hollow_thrall";
    assert.ok(codes([king(), e], "hollow_siege", BM_RIGS, "errors").includes("rig_on_boss"));
  });
  it("a missing rig is a WARNING (vanilla fallback), not an error; unchecked contexts say so", () => {
    assert.ok(codes(loadBmDesigns(), "hollow_king", ["hollow_thrall"]).includes("rig_unresolved"));
    assert.deepEqual(codes(loadBmDesigns(), "hollow_king", ["hollow_thrall"], "errors"), []);
    assert.ok(codes(loadBmDesigns(), "hollow_king").includes("rig_unchecked"));
    assert.ok(codes(loadBmDesigns(), "hollow_siege", ["hollow_king"]).includes("rig_unresolved"), "wave rig checked too");
  });
  it("sounds are checked like every boss sound; a custom clip and display equipment are flagged", () => {
    const k = king(); k.model!.sounds = { hurt: "nx_other123:x.hurt" };
    assert.ok(codes([k, siege()], "hollow_king", BM_RIGS, "errors").includes("foreign_namespace"));
    const c = king(); c.model!.clips = { phase: "roar" }; c.equipment = { helmet: "minecraft:golden_helmet" };
    const w = codes([c, siege()], "hollow_king", BM_RIGS);
    assert.ok(w.includes("clip_custom") && w.includes("model_equipment"), w.join(","));
  });
  it("the JSON Schema file carries the new fields", () => {
    const t = fs.readFileSync(path.join(ROOT, "lib/cyrus/designer/boss.v1.schema.json"), "utf8");
    for (const k of ['"model"', '"rig"', '"clips"', '"phase"']) assert.ok(t.includes(k), k);
  });
});

describe("boss model: compiler", () => {
  it("wears the rigs: BossModels, depend, deps per version, main class wiring, generated calls", () => {
    for (const ver of BM_VERSIONS) {
      const r = compileBm(ver);
      assert.deepEqual(r.rigsApplied, BM_RIGS);
      assert.deepEqual(r.deps, bossModelDeps(ver));
      assert.ok(fileOf(r, BOSS_MODEL_COMPONENT.file).includes("public final class BossModels implements Bosses.Body"));
      assert.match(fileOf(r, "plugin.yml"), /^depend: \[BetterModel\]$/m);
      assert.ok(fileOf(r, "HollowKing.java").includes("bosses.body(new BossModels(bosses));"));
      const b = fileOf(r, "bosses/HollowKingBoss.java");
      for (const s of [`modelKey = "${NS}_hollow_king";`, `clipPhase = "hurt";`, `modelSounds.put("hurt", "${NS}:hollow_king.hurt");`, `"${NS}_hollow_thrall", 1.0);`]) assert.ok(b.includes(s), s);
      assert.ok(fileOf(r, "encounters/HollowSiegeEncounter.java").includes(`"${NS}_hollow_thrall", 1.0);`));
      assert.match(r.readme, /wears the animated creature hollow king/);
    }
    assert.deepEqual(bossModelDeps("1.21.11"), ["bettermodel-api-2", "bettermodel-bukkit-api-2"]);
    assert.deepEqual(bossModelDeps("26.2"), ["bettermodel-api", "bettermodel-bukkit-api"]);
  });
