    const on = req({ bosses: true }, { bossModels: true });
    assert.equal(on.creature, true); assert.equal(on.bossModel, true); assert.equal(on.laneOff, undefined);
    const items = req({}, { bossModels: true });
    assert.equal(items.creature, false, "no bosses part: nothing could wear it");
    const plain = TX.parseAssetsRequest({ namespace: NS, creature: true }, "1.21.11", new Set(), ok, ok, new Set(["1.21.11"]), ok, ok, new Set(), { bossModels: true });
    assert.equal(plain.creature, true); assert.equal(plain.bossModel, undefined, "plain creature builds unchanged");
  });
  it("prompt: the cross-reference is appended only with design + bosses + creature + bossModel, and is tiny", () => {
    const P = require(path.join(ROOT, "services/modbuilder/prompts.js"));
    const base = { design: true, bosses: true, creature: true };
    const without = P.systemPrompt("1.21.11", base), withIt = P.systemPrompt("1.21.11", { ...base, bossModel: true });
    assert.equal(withIt, without + P.BOSS_MODEL_SECTION, "appended right after the boss part, nothing else changes");
    assert.equal(P.systemPrompt("1.21.11", { design: true, bosses: true, bossModel: true }), P.systemPrompt("1.21.11", { design: true, bosses: true }), "no creature lane: byte-identical");
    const tokens = Math.ceil(P.BOSS_MODEL_SECTION.length / 4);
    assert.ok(tokens <= 150, `prompt delta ~${tokens} tokens`);
    const ab = P.assetsBlock ? P.assetsBlock({ namespace: NS, design: true, bosses: true, creature: true, bossModel: true }) : "";
    if (ab) assert.match(ab, /a boss wears one with "model":\{"rig":"<name>"\}/);
