    assert.equal(P.systemPrompt("1.21.11", { design: true, bosses: true, bossModel: true }), P.systemPrompt("1.21.11", { design: true, bosses: true }), "no creature lane: byte-identical");
    const tokens = Math.ceil(P.BOSS_MODEL_SECTION.length / 4);
    assert.ok(tokens <= 150, `prompt delta ~${tokens} tokens`);
    const ab = P.assetsBlock ? P.assetsBlock({ namespace: NS, design: true, bosses: true, creature: true, bossModel: true }) : "";
    if (ab) assert.match(ab, /a boss wears one with "model":\{"rig":"<name>"\}/);
  });
  it("designer route: creature soft checks talk about the design, and are quiet when the boss wears it", () => {
    const CR = require(path.join(ROOT, "services/modbuilder/creatures.js"));
    const ws = fs.mkdtempSync(path.join(os.tmpdir(), "cyrus-bm-cre-"));
    fs.mkdirSync(path.join(ws, "assets/creatures"), { recursive: true });
    for (const n of BM_RIGS) fs.writeFileSync(path.join(ws, `assets/creatures/${n}.json`), JSON.stringify(loadBmRig(n)));
    const r = compileBm("1.21.11");
    for (const f of r.files) { const abs = path.join(ws, f.path); fs.mkdirSync(path.dirname(abs), { recursive: true }); fs.writeFileSync(abs, f.content); }
    const java = r.files.filter((f) => f.path.endsWith(".java")).map((f) => ({ rel: f.path, abs: path.join(ws, f.path) }));
    const c = CR.checkWorkspaceCreatures(ws, { namespace: NS, javaFiles: java, pluginYml: fileOf(r, "plugin.yml"), designer: true });
    assert.deepEqual(c.problems, []); assert.deepEqual(c.soft, []);
    const none = compileBm("1.21.11", []);
    const java2 = none.files.filter((f) => f.path.endsWith(".java")).map((f) => { const abs = path.join(ws, "n", f.path); fs.mkdirSync(path.dirname(abs), { recursive: true }); fs.writeFileSync(abs, f.content); return { rel: f.path, abs }; });
    const c2 = CR.checkWorkspaceCreatures(ws, { namespace: NS, javaFiles: java2, designer: true });
    assert.ok(c2.soft.some((s: string) => s.includes(`no boss wears this creature: add "model":{"rig":"hollow_king"}`)), c2.soft.join("\n"));
    fs.rmSync(ws, { recursive: true, force: true });
  });
  it("service workspace: rigs from assets/creatures feed the design compile; summary.rigsApplied; service == TypeScript", () => {
    const DZS = require(path.join(ROOT, "services/modbuilder/designs.js"));
    const ws = fs.mkdtempSync(path.join(os.tmpdir(), "cyrus-bm-ws-"));
    fs.mkdirSync(path.join(ws, "assets/designs"), { recursive: true });
    fs.mkdirSync(path.join(ws, "assets/creatures"), { recursive: true });
    for (const d of loadBmDesigns()) fs.writeFileSync(path.join(ws, `assets/designs/${d.id}.json`), JSON.stringify(d));
    fs.writeFileSync(path.join(ws, "assets/creatures/hollow_king.json"), JSON.stringify(loadBmRig("hollow_king")));
    fs.writeFileSync(path.join(ws, "assets/creatures/hollow_thrall.json"), JSON.stringify({ ...loadBmRig("hollow_thrall"), hitbox: { width: 9, height: 1 } }));
    assert.deepEqual(DZS.rigNamesOf(ws, NS), ["hollow_king"], "a rig that fails the RigSpec check is not wearable");
    fs.writeFileSync(path.join(ws, "assets/creatures/hollow_thrall.json"), JSON.stringify(loadBmRig("hollow_thrall")));
    const chk = DZS.checkWorkspaceDesigns(ws, { namespace: NS, mcVersion: "1.21.11" });
    assert.ok(chk.results.every((x: { ok: boolean }) => x.ok), JSON.stringify(chk.problems));
    const c = DZS.compileWorkspaceDesigns(ws, { pluginName: BM_PLUGIN, mcVersion: "1.21.11", assets: { namespace: NS } }, chk.results.map((x: { spec: unknown }) => x.spec));
    assert.ok(c.ok, JSON.stringify(c.errors));
    assert.deepEqual(c.summary.rigsApplied, BM_RIGS);
    assert.deepEqual(c.summary.deps, ["bettermodel-api-2", "bettermodel-bukkit-api-2"]);
    assert.equal(c.summary.hash, compileBm("1.21.11").hash);
    assert.match(fs.readFileSync(path.join(ws, "src/main/resources/plugin.yml"), "utf8"), /depend: \[BetterModel\]/);
    fs.rmSync(ws, { recursive: true, force: true });
  });
  it("lane gaps: a worn creature is delivered; a creature no boss wears is a gap with that reason", () => {
    const LG = require(path.join(ROOT, "services/modbuilder/lanegaps.js"));
    const assets = { creature: true, design: true, bosses: true, plan: [{ lane: "creature", what: "the Hollow King's body" }, { lane: "designBoss", what: "boss" }] };
    assert.deepEqual(LG.laneGaps(assets, { creatures: 1, designs: 2 }, []), []);
    const g = LG.laneGaps(assets, { creatures: 0, designs: 2 }, [], { creature: "the build wrote the creature, but no boss design wears it" });
    assert.equal(g.length, 1); assert.equal(g[0].state, "empty"); assert.match(g[0].sentence, /no boss design wears it/);
  });
});

describe("boss model: portal + oracle", () => {
  it("portal re-compile reproduces the service's jar sources only with the rigs the service attached", () => {
    const r = compileBm("1.21.11");
    const list = loadBmDesigns().map((d) => ({ name: d.id, path: `assets/designs/${d.id}.json`, sha256: "x", spec: d }));
    const agreed = checkReturnedDesigns(list, { namespace: NS, mcVersion: "1.21.11", pluginName: BM_PLUGIN, compile: { hash: r.hash, pluginName: BM_PLUGIN, configVersion: r.configVersion, rigsApplied: r.rigsApplied } });
    assert.equal(agreed.serviceAgreed, true);
    const old = checkReturnedDesigns(list, { namespace: NS, mcVersion: "1.21.11", pluginName: BM_PLUGIN, compile: { hash: r.hash, pluginName: BM_PLUGIN, configVersion: r.configVersion } });
    assert.equal(old.serviceAgreed, false, "a service that attached nothing compiled vanilla bodies");
    assert.ok(!old.compiled!.files.some((f) => f.path.endsWith("BossModels.java")));
  });
  it("oracle: a boss wearing a flown creature (BetterModel in the flight) gets the tag + status probes", () => {
    const r = compileBm("1.21.11");
    const input = { version: "1.21.11", pluginName: BM_PLUGIN, namespace: NS, pluginYml: fileOf(r, "plugin.yml"), configYml: fileOf(r, "config.yml"), designs: loadBmDesigns().map((d) => ({ name: d.id, spec: d })), creatures: BM_RIGS.map((n) => ({ name: n })), engines: ["BetterModel"] };
    const ex = deriveExpectations(input);
    const boss = ex.find((e) => e.kind === "boss_spawns" && e.title.includes("hollow_king") || e.kind === "boss_spawns" && e.title.includes("wearing"));
    assert.ok(boss, JSON.stringify(ex.map((e) => e.title)));
    const txt = JSON.stringify(boss);
    assert.ok(txt.includes(`tag=${NS}.model`) && txt.includes(`model ${NS}_hollow_king attached`), txt);
    const cre = ex.find((e) => e.kind === "creature_spawns" && e.title.includes("hollow_king"));
    assert.match(String((cre as { why?: string } | undefined)?.why ?? JSON.stringify(cre)), /worn by the boss hollow_king/);
    const noEngine = deriveExpectations({ ...input, engines: [] });
    assert.ok(!JSON.stringify(noEngine.find((e) => e.kind === "boss_spawns")).includes(`${NS}.model`), "no engine: no model probe");
  });
  it("the two rigs compile to .bbmodel files that fit the Test Flight file limit", () => {
    for (const m of bmModels()) assert.ok(m.bytes < 64 * 1024, `${m.key} ${m.bytes} bytes`);
  });
});

